{
  "$schema": "https://opencode.ai/config.json",
  "model": "azure/deepseek-v4-flash",
  "small_model": "azure/deepseek-v4-flash",
  "permission": "allow",
  "plugin": [
    "./adapter/src/plugin.ts"
  ]
}

{
  "name": "@alonzo/adapter",
  "version": "0.1.0",
  "private": true,
  "description": "Alonzo opencode plugin adapter — substrate bridge between opencode and @alonzo/core",
  "type": "module",
  "main": "./src/plugin.ts",
  "exports": {
    ".": "./src/plugin.ts",
    "./hooks": "./src/hooks.ts",
    "./driver": "./src/driver.ts",
    "./registry": "./src/registry.ts",
    "./session-manager": "./src/session-manager.ts",
    "./v2-client": "./src/v2-client.ts",
    "./effects": "./src/effects.ts",
    "./gates": "./src/gates.ts",
    "./response-capture": "./src/response-capture.ts",
    "./launch": "./src/launch.ts"
  },
  "scripts": {
    "typecheck": "bun --bun ./node_modules/.bin/tsc --noEmit -p tsconfig.base.json"
  },
  "dependencies": {
    "@alonzo/core": "workspace:*",
    "@opencode-ai/plugin": "1.17.19",
    "@opencode-ai/sdk": "1.17.19"
  },
  "devDependencies": {
    "@types/bun": "latest",
    "typescript": "^5.5.0"
  }
}

{
  "name": "@alonzo/controller",
  "version": "0.1.0",
  "private": true,
  "type": "module",
  "description": "Alonzo local project controller: project registry, workflow template catalog, bridge discovery",
  "main": "./src/index.ts",
  "types": "./src/index.ts",
  "exports": {
    ".": "./src/index.ts",
    "./cli": "./src/cli.ts"
  },
  "scripts": {
    "typecheck": "bun --bun ./node_modules/.bin/tsc --noEmit -p tsconfig.json",
    "test": "bun test"
  },
  "dependencies": {
    "@alonzo/core": "workspace:*"
  },
  "devDependencies": {
    "@types/bun": "latest",
    "typescript": "^5.5.0"
  }
}

{
  "name": "@alonzo/core",
  "version": "0.1.0",
  "private": true,
  "type": "module",
  "description": "Alonzo core workflow engine: YAML format, runner phase machine, trace writer",
  "main": "./src/index.ts",
  "types": "./src/index.ts",
  "exports": {
    ".": "./src/index.ts",
    "./format": "./src/format/index.ts",
    "./format/schema": "./src/format/schema.ts",
    "./runner": "./src/runner/index.ts",
    "./substrate": "./src/substrate/index.ts",
    "./trace": "./src/trace/index.ts",
    "./protocol": "./src/protocol/index.ts"
  },
  "scripts": {
    "typecheck": "bun --bun ./node_modules/.bin/tsc --noEmit -p tsconfig.json",
    "test": "bun test",
    "gen:schema": "bun run scripts/gen-schema.ts"
  },
  "dependencies": {
    "yaml": "^2.5.0"
  },
  "devDependencies": {
    "@types/bun": "latest",
    "typescript": "^5.5.0"
  }
}
